from typing import List, Tuple

def minSubArraySum(nums: List[int]) -> int:
    min_sum = float('inf')
    n = len(nums)
    for i in range(n):
        current_sum = nums[i]
        for j in range(i, n):
            current_sum += nums[j]
            if current_sum < min_sum:
                min_sum = current_sum
    return min_sum if min_sum != float('inf') else nums[0] if nums else 0
